/** Real registry-aware native item codecs and DFU, including dynamic enchantment lookups. */
@EventBusSubscriber(modid="vandorlabs")
public final class StorageItemCodecChecks {
 private static int checks;private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Storage codec: "+why);}
 private static void run(ServerLevel level)throws Exception{JsonObject source;try(var stream=new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.storageItemReference"))));var reader=new InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)){source=JsonParser.parseReader(reader).getAsJsonObject();}need(source.get("sourceDataVersion").getAsInt()==NativeInventoryItems.SOURCE_DATA_VERSION,"actual Source runtime data version");var sourceIds=new java.util.HashSet<String>();for(var id:source.getAsJsonArray("vanillaItems"))sourceIds.add(id.getAsString());need(sourceIds.equals(NativeInventoryItems.sourceVanillaItems()),"all actual Source vanilla item IDs");int accepted=0,refused=0;for(var value:source.getAsJsonArray("cases")){var row=value.getAsJsonObject();String label=row.get("label").getAsString();var raw=TagParser.parseTag(row.get("raw").getAsString());var before=raw.copy();boolean supported=java.util.Set.of("bare-air","plain","metadata-name","durability-enchantment","named-sword","written-book","container","shulker-container","actual-shulker-drop","credential","nested-credential").contains(label);try{var stack=NativeInventoryItems.legacy(raw,level.registryAccess());need(supported,"unsupported ownership accepted "+label);need(stack.getCount()==row.get("count").getAsInt(),"Source count "+label);var encoded=NativeInventoryItems.write(stack,level.registryAccess());need(net.minecraft.world.item.ItemStack.isSameItemSameComponents(stack,NativeInventoryItems.modern(encoded,level.registryAccess())),"real native codec roundtrip "+label);switch(label){case "metadata-name"->need(stack.is(net.minecraft.world.item.Items.GRANITE)&&stack.getHoverName().getString().equals("Legacy granite"),"metadata/name migration");case "durability-enchantment"->{need(stack.getDamageValue()==41,"durability");need(encoded.getCompound("components").getCompound("minecraft:enchantments").getCompound("levels").getInt("minecraft:efficiency")==3,"actual dynamic enchantment codec");}case "named-sword"->{need(stack.getDamageValue()==13&&stack.getHoverName().getString().equals("Legacy blade"),"named durable sword");need(stack.get(DataComponents.LORE).lines().size()==2,"lore migration");need(encoded.getCompound("components").getCompound("minecraft:enchantments").getCompound("levels").getInt("minecraft:sharpness")==5,"named enchantment");}case "credential"->need(com.vandorlabs.neoforge.credentials.NativeCredentialItems.company(stack)==2&&com.vandorlabs.neoforge.credentials.NativeCredentialItems.legacyCredentialData(stack).equals(raw),"proven credential retains opaque original");case "nested-credential"->{var nested=stack.get(DataComponents.CONTAINER).getStackInSlot(0);need(com.vandorlabs.neoforge.credentials.NativeCredentialItems.company(nested)==2&&com.vandorlabs.neoforge.credentials.NativeCredentialItems.legacyCredentialData(nested).getCompound("ForgeCaps").contains("foreign:chip"),"nested credential staged before vanilla parent conversion");}case "written-book"->need(stack.get(DataComponents.WRITTEN_BOOK_CONTENT)!=null,"written book component");case "container","shulker-container","actual-shulker-drop"->{var entries=encoded.getCompound("components").getList("minecraft:container",Tag.TAG_COMPOUND);need(entries.size()==1&&entries.getCompound(0).getCompound("item").getInt("count")== (label.equals("container")?9:3),"nested physical item preserved "+label);}default->{}}accepted++;}catch(RuntimeException failure){if(supported)throw new IllegalStateException("Supported Source item "+label,failure);refused++;}need(raw.equals(before),"original item snapshot untouched "+label);}var zeroCaps=TagParser.parseTag("{id:\"minecraft:iron_ingot\",Count:0b,ForgeCaps:{\"foreign:owned\":{Marker:7}}}");boolean zeroRefused=false;try{NativeInventoryItems.legacy(zeroCaps,level.registryAccess());}catch(IllegalArgumentException expected){zeroRefused=true;}need(zeroRefused,"zero-count item must not erase opaque capability owner");var unknownNested=TagParser.parseTag("{id:\"minecraft:chest\",count:1,components:{\"minecraft:container\":[{slot:0,item:{id:\"missing:owned\",count:1}}]}}");boolean nestedRefused=false;try{NativeInventoryItems.modern(unknownNested,level.registryAccess());}catch(RuntimeException expected){nestedRefused=true;}need(nestedRefused,"actual native codec refuses unknown nested item ownership");var futureSlot=TagParser.parseTag("{id:\"minecraft:chest\",count:1,components:{\"minecraft:container\":[{slot:0,item:{id:\"minecraft:iron_ingot\",count:1},FutureInventory:{Items:[]}}]}}");boolean futureRefused=false;try{NativeInventoryItems.modern(futureSlot,level.registryAccess());}catch(RuntimeException expected){futureRefused=true;}need(futureRefused,"unknown native nested ownership cannot disappear through permissive codec");var deep=TagParser.parseTag("{id:\"minecraft:iron_ingot\",count:1}");for(int i=0;i<33;i++){var parent=TagParser.parseTag("{id:\"minecraft:chest\",count:1}");var component=new CompoundTag();var list=new ListTag();var slot=new CompoundTag();slot.putInt("slot",0);slot.put("item",deep);list.add(slot);component.put("minecraft:container",list);parent.put("components",component);deep=parent;}boolean deepRefused=false;try{NativeInventoryItems.modern(deep,level.registryAccess());}catch(IllegalArgumentException expected){deepRefused=true;}need(deepRefused,"native nested item depth refuses before codec recursion");boolean unmarkedRefused=false;try{NativeInventoryItems.legacy(TagParser.parseTag("{id:\"minecraft:diamond\",count:3}"),level.registryAccess());}catch(IllegalArgumentException expected){unmarkedRefused=true;}need(unmarkedRefused,"unmarked modern owner must not appear as empty legacy Count");need(accepted==11&&refused==7,"Source item corpus coverage");System.out.println("[vandorlabs][storage-codec] PASS checks="+checks+" accepted="+accepted+" refused="+refused+" actual native registry/DFU/name/damage/enchantment/container codecs");}
 private static void inventory(ServerLevel level)throws Exception{JsonObject source;try(var stream=new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.storageReference"))));var reader=new InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)){source=JsonParser.parseReader(reader).getAsJsonObject();}int accepted=0,refused=0;for(var value:source.getAsJsonArray("snapshots")){var row=value.getAsJsonObject();var raw=TagParser.parseTag(row.get("input").getAsString());var original=raw.copy();var previous=NativeStorageInventory.empty();int seed=row.get("seed").getAsInt();if(seed>0)previous.set(26,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND,seed==1?7:64));boolean unsupported=raw.get("Items") instanceof ListTag list&&!list.isEmpty()&&list.getElementType()==Tag.TAG_COMPOUND&&list.getCompound(0).getString("id").equals("missing:opaque")||raw.toString().contains("Slot:27b");try{var slots=NativeStorageInventory.read(raw,level.registryAccess(),previous);need(!unsupported,"unsupported physical owner accepted");var expected=row.getAsJsonArray("slots");for(int i=0;i<27;i++){var slot=expected.get(i).getAsJsonObject();need(slots.get(i).getCount()==slot.get("count").getAsInt(),"Source slot count "+accepted+"/"+i);if(!slots.get(i).isEmpty()){String id=slot.get("item").getAsString();if(id.equals("minecraft:stone")&&slot.get("damage").getAsInt()==1)id="minecraft:granite";need(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(slots.get(i).getItem()).toString().equals(id),"Source slot identity");}}var saved=new CompoundTag();NativeStorageInventory.write(saved,slots,level.registryAccess());var copy=NativeStorageInventory.read(saved,level.registryAccess(),NativeStorageInventory.empty());for(int i=0;i<27;i++)need(net.minecraft.world.item.ItemStack.matches(slots.get(i),copy.get(i)),"native slot codec roundtrip");accepted++;}catch(RuntimeException failure){if(!unsupported)throw failure;refused++;}need(raw.equals(original)&&previous.get(26).getCount()==(seed==0?0:seed==1?7:64),"staging leaves original/previous owner intact");}need(accepted==33&&refused==6,"Source inventory staging coverage");var before=NativeStorageInventory.empty();before.set(26,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND,7));var late=TagParser.parseTag("{Items:[{Slot:0b,id:\"minecraft:iron_ingot\",Count:4b},{Slot:26b,id:\"missing:owner\",Count:1b}]}");boolean failed=false;try{NativeStorageInventory.read(late,level.registryAccess(),before);}catch(IllegalArgumentException expected){failed=true;}need(failed&&before.get(0).isEmpty()&&before.get(26).getCount()==7,"late slot failure publishes no prefix");var empty=new CompoundTag();NativeStorageInventory.write(empty,NativeStorageInventory.empty(),level.registryAccess());need(NativeStorageInventory.read(empty,level.registryAccess(),before).stream().allMatch(net.minecraft.world.item.ItemStack::isEmpty),"complete empty native envelope suppresses stale contents");empty.putInt(NativeStorageInventory.SCHEMA,99);boolean future=false;try{NativeStorageInventory.read(empty,level.registryAccess(),before);}catch(IllegalArgumentException expected){future=true;}need(future,"future inventory schema refused");System.out.println("[vandorlabs][storage-inventory-codec] PASS accepted="+accepted+" refused="+refused+" checks="+checks+" all27slots staged/repeated legacy reads/native roundtrip/late failure/empty envelope");}
 @SubscribeEvent public static void started(ServerStartedEvent event){if(!"storage-codec".equals(System.getProperty("vandorlabs.transmitterPhase")))return;try{run(event.getServer().overworld());inventory(event.getServer().overworld());}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][storage-codec] FAIL "+failure);}finally{event.getServer().halt(false);}}
}
